import{_ as e,c as p,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"巽","description":"高島易斷 - 巽","frontmatter":{"title":"巽","description":"高島易斷 - 巽"},"headers":[],"relativePath":"classics/takashima/057.md","filePath":"classics/takashima/057.md"}'),i={name:"classics/takashima/057.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="巽" tabindex="-1">巽 <a class="header-anchor" href="#巽" aria-label="Permalink to “巽”">​</a></h1><h2 id="巽-1" tabindex="-1">巽 <a class="header-anchor" href="#巽-1" aria-label="Permalink to “巽”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>巽：小亨，利有攸往，利見大人。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《巽》本《乾》體，《乾》德元亨，亦稱大亨，初動成《巽》，純剛化柔，故為“小亨”。卦《彖》言“利有攸往”者，《大過》、《恆》、《益》，皆取《巽》也，過剛之人，所往必窮，《巽》以《坤》初一陰入《乾》，以柔濟剛，黽勉前往，《巽》為利，故“利有攸往”。“大人”，指二五，《巽》二五皆《乾》體，《乾》二五皆“利見大人”，《巽》之《彖》辭，從《乾》來，《乾》為利，上互《離》，《離》為見，故《巽》《彖》亦曰“利見大人”。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>隨風，巽。君子以申命行事。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>“隨”者，相繼之義，“申命行事”者，申告君命而奉行之也。《巽》為從，從者，隨也；又《巽》為風，以風隨風，無乎不入，故曰“隨風”。“隨風”者，猶言從風，即“重巽”之謂也。風行相隨，所向皆靡，號令所施，順合民心，民無不從，所謂“君子之德風”也。又上卦之《巽》，為大君施命之象。下卦之《巽》，為臣民奉命之象，夫君命臣行，君臣之大義也，故曰“君子以申命行事”。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：運途順遂，百事盛宜。</p><p>○　問營商：商業最宜隨機應變，聽命而行，斯可獲利。</p><p>○　問功名：“風從虎”，有虎變之象焉。</p><p>○　問戰徵：軍令之行，捷如風火，令出惟行，無可遲疑。</p><p>○　問婚姻：憑父母之命，媒妁之言，禮之正也。夫唱婦隨，百年偕老，吉。</p><p>○　問疾病：是風痺之症，須人扶持而行。</p><p>○　問訟事：須重申稟訴。</p><p>○　問失物：為風飄失，須重番尋覓，或可復得。</p><p>○　問六甲：生女。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>初爻陰柔居下，為《巽》之主，巽，順也，柔順少斷，故象為進退。狐疑不決，每見於發念之初，蓄疑敗謀，此志之所以不治也。《巽》反成《兌》，《兌》為武人，武人果決，足以斷疑，故曰“利武人之貞”。“貞”者，正也，斯剛強奮發之氣，可以矯逡巡畏縮之偏。《象傳》釋以“志治”，是以武治疑，即以《兌》制《巽》也。</p><h2 id="初六佔" tabindex="-1">初六佔 <a class="header-anchor" href="#初六佔" aria-label="Permalink to “初六佔”">​</a></h2><p>○　問時運：運途不正，心神猶豫，是以謀事皆顛倒無成。</p><p>○　問營商：《巽》本為利，因疑而敗，以斷而成，知猶豫者必難獲利也。</p><p>○　問功名：就武可成。</p><p>○　問婚姻：不在彬彬文士，而宜桓桓虎臣。</p><p>○　問家宅：此宅朝東南，地位不當，進退不便，宜改朝西為利。</p><p>○　問六甲：生女。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>友人某來，請佔氣運，筮得《巽》之《小畜》。</p><p>斷曰：巽者，風也，風之為物，或東或西，來去無常，猶多疑之人，進退無定也。“武人”者，取其剛果能斷也。今足下佔氣運，得此初爻，《巽》為七八月之卦，《巽》又為木，知足下現交木運，時值初秋，木因風吹，搖動不定，喻言人心疑慮，以致進退不決。“武人”者肅殺之象也，天以肅殺而成秋，猶人以剛決而成事，足下一味巽柔，臨事不斷，渾如隨風飄蕩，毫無定見，本為畏事，不知反以多事。勸足下當以沉潛剛克處之，為得其正矣。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>《巽》為床，床下為初，《巽》以一陰在下，故曰“床下”。凡陰氣中人，必使其人神魂不定，疑鬼疑神，若有物憑之者焉，非用剛克，不能去其疑妄。“史”者掌卜筮之官，“巫”者掌祓禳之官，皆取諸《兌》象。《兌》又為附決，用史以釋疑，用巫以禳災，斯得感格於上下神祗，而吉祥彙集也，故曰“紛若，吉”。“紛”，眾多之稱，“若”，語辭。《象傳》以“得中”釋之，謂能行得其中，以感孚夫神祗，是以有“紛若”之吉也。</p><h2 id="九二佔" tabindex="-1">九二佔 <a class="header-anchor" href="#九二佔" aria-label="Permalink to “九二佔”">​</a></h2><p>○　問時運：得神明保佑，運途多吉。</p><p>○　問營商：凡販運貨物，有不決者，宜問諸卜筮，自能迪吉。</p><p>○　問功名：得有神助，吉。</p><p>○　問戰徵：地位既低，進退兩難，當此之時，惟告求神明，自可獲吉。無咎。</p><p>○　問婚姻：卜之則吉。</p><p>○　問家宅：宜禱。</p><p>○　問疾病：宜祭禱床公床婆，自得無咎。</p><p>○　問六甲：生女。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>某縉紳來，請佔方今時勢，筮得《巽》之《漸》。</p><p>斷曰：巽者，柔順也，其為人必柔弱無能，亦優柔寡斷。九二曰“巽在床下”，有匍匐床下，俯首乞憐之狀也。足下佔時勢，得此爻辭，知方今時勢，朝野上下，一以巽諛成風，以忠厚為迂疏，以奸詐為得計，所謂伺候於公卿之門，奔走於形勢之途，今之士大夫所恃為進身之要策也。不知愈趨愈下，世道日衰，而禍患之來，皆其自取。爻辭曰“用史巫紛若，吉”，蓋明示以卑《巽》之道，用之權貴，則謂諂諛，用之於神明，則謂誠求，誠求於神，神必佑之，是以吉而無咎也。足下有心挽回時勢，可知所從事矣。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>三爻以陽居陽，處下《巽》之極。“頻”者，數也，下《巽》終而上《巽》接，故曰“頻巽”。所謂“剛巽乎中正”，固非徒取夫巽也，九三乃亟亟於巽以繼巽，若一巽為不足，而又加一巽焉，是第知巽之為巽，而不知制《巽》之道，偏於巽者也。偏則吝矣，吝則窮矣。《象傳》以“志窮”釋之，三居《巽》之終，志卑道屈，是終窮也。</p><h2 id="九三佔" tabindex="-1">九三佔 <a class="header-anchor" href="#九三佔" aria-label="Permalink to “九三佔”">​</a></h2><p>○　問時運：目下運途卑低，未免為人所賤。</p><p>○　問戰徵：一味委靡，力弱志衰，難以免辱。</p><p>○　問功名：卑而又卑，所得亦微矣。</p><p>○　問營商：巽順過甚，未能與人爭強，何能獲利？</p><p>○　問婚姻：門戶低微，成亦可羞。</p><p>○　問家宅：屋宇低小，必是貧窮之戶。</p><p>○　問訟事：柔弱被欺，咎亦自取。</p><p>○　問六甲：生女。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>友人某來，請佔氣運，筮得《巽》之《渙》。</p><p>斷曰：九三處內外卦之間，巽而又巽，謂之“重巽”，是一味委靡，不能免禍，反致啟羞。足下佔氣運，得此爻辭，知目下氣運柔弱，無力奮興。當以《彖傳》所謂“剛巽乎中正”者處之，斯巽得其濟，而足以自強，則其志可行，其道不窮矣。</p><p>明治三十年，佔貴族院氣運，筮得《巽》之《渙》。</p><p>斷曰：爻曰“頻巽”，是上下皆《巽》，《正義》以頻為頻戚憂戚之容，謂志意窮屈，不得申遂，處《巽》之時，只得受其屈辱，故曰“頻巽，吝”。今佔貴族院，得此爻辭，知方今院中議員，皆以巽順為懷，行《巽》之道，處《巽》之時，志窮力弱，只得受其屈辱，以致頻戚不樂也。本年貴族院，必無功績可見。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>四為重《巽》之主，得正而順乎剛，故“悔亡”。四與初同體，初曰“利武人”，取《離》之為甲冑，為弓矢，四曰“田”，亦取《離》之為網罟也，其象亦相同。《周禮》四時之田，皆前期示戒，及其聽命，即《大象》所云“申命行事”之義也。“獲”，田所獲也”。“三品”者，一為幹豆，二為賓客，三為充君之庖。《象傳》以“有功”釋之，如《詩·豳風》所詠：“獻豜私豵，載續武功”，謂致禽獸而有功也。一雲，《解》九二曰“田獲三狐”，言去小人也；《巽》九四曰“田獲三品”，言用君子也。</p><h2 id="六四佔" tabindex="-1">六四佔 <a class="header-anchor" href="#六四佔" aria-label="Permalink to “六四佔”">​</a></h2><p>○　問時運：運途得正，災悔俱亡，出而有功也。</p><p>○　問戰徵：從東南進兵，自得斬獲有功。</p><p>○　問功名：當以獻功獲賞，出身成名。</p><p>○　問營商：當以採辦皮革羽毛等品致富。</p><p>○　問婚姻：婚禮，古時弋鳧射雀，亦田象。</p><p>○　問疾病：曰“悔亡”，病必可愈。</p><p>○　問失物：可得。</p><p>○　問六甲：生女。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>橫濱某商來謂曰：僕今欲謀一事，請佔其得失。筮得《巽》之《姤》。</p><p>斷曰：《巽》為近市利三倍之卦，六四為重《巽》之主，足以當之。今佔得四爻，四“悔亡，田獲三品”，是明言無悔而有獲也。子之謀事，其有大利可知也。子勿疑，舉全力而從事可也。某大喜，乃彙集資金，直赴日光會津地方，採買人參，轉售與清商，果得大利雲。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>九五居卦之尊，中而且正，是即“剛巽乎中正”之大人也，故諸吉俱備。“先庚三日”為丁，丁者，取叮嚀告誡之意，“後庚三日”為癸，癸者，取揆度周詳之義。卦體五動成《蠱》，《蠱》六五曰“先甲三日”辛，“後甲三日”丁，《巽》九五曰“先庚三日”丁。《蠱》終於丁，而《巽》則始於丁，不始於“先甲”之辛，為“無初”也；癸為十干之終，《巽》終“後庚”之癸，為“有終”矣，故曰“無初有終”。《蠱》為三月之卦，春旺於木，故用甲；《巽》為八月之卦，秋旺於金，故用庚。木腐生蟲成《蠱》，《巽》用金克之，斯不至變而為《蠱》矣，故《蠱》用甲，而“小有悔，無大咎”；《巽》用庚，乃得“貞吉”而“悔亡”。《象傳》即以位釋之，謂其“中正”而得吉也。凡六十四卦中，於九五言“貞吉悔亡”者，惟此一卦而已。</p><h2 id="九五佔" tabindex="-1">九五佔 <a class="header-anchor" href="#九五佔" aria-label="Permalink to “九五佔”">​</a></h2><p>○　問時運：逢丁癸日作事，無往不利，大吉。</p><p>○　問營商：生業宜取木爻，日辰宜用金日，初有小悔，後必大利，吉。</p><p>○　問功名：位得中正，爻曰“貞吉”，逢丁癸之年，必得成名。</p><p>○　問戰徵：其於師旅，必叮嚀以告誡，其於地勢，必周詳以揆度。臨事好謀，先後不怠，故戰無不勝，大吉。</p><p>○　問婚姻：丁火癸水，水火相配，吉。</p><p>○　問家宅：其宅坐北向南，地位中正，大吉。</p><p>○　問疾病：三日可愈。</p><p>○　問六甲：生女。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>明治二十四年，佔某貴顯氣運，筮得《巽》之《蠱》。</p><p>斷曰：據爻象而論，氣運以金水為旺相，自丁至癸，七年間正交盛運，所謂“貞吉，悔亡，無不利”也。《大象》曰“位得中正”，知貴下本年必升晉顯職，祿位益隆，正當有為之時也；卦體九五動，變六五為《蠱》，《蠱》者腹內蟲也，喻言國政之內亂也。貴下能法乎《巽》之用庚，庚者更也，以《巽》行權，因時制宜，更舊從新，命必以叮嚀申之，事必以揆度行之，《彖傳》所謂“剛巽乎中正而志行”者，是在貴下焉。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>上與初為終始，初在下多疑，既示以“武人之貞”；至於上居卦之極，位高責重，任事益當勇決，何得一味畏葸，自甘退伏，同於二之床下？宜其高而益危，無以自立也。“資斧”者，虞喜《志林》雲資當作齋，齋戒入廟而受斧，謂上身居高位，入廟受斧，自足振其威權者也，蓋即初利用武人之義；乃巽順不斷，失其威權，是即所謂“喪其齋斧”也。畏事而事益滋，避禍而禍反集，故曰“貞兇”。《傳》以“上窮”釋“在床下”，以上之高居廊廟，畏首畏尾，無異伏處床第，其窮為可哀也。以“正乎兇”釋“貞兇”，明過《巽》者之失其正矣，失其正，是以兇也。</p><h2 id="上九佔" tabindex="-1">上九佔 <a class="header-anchor" href="#上九佔" aria-label="Permalink to “上九佔”">​</a></h2><p>○　問時運：運途不正，作事委靡，愈高愈危，有喪無得，兇。</p><p>○　問戰徵：身為主帥，畏首畏尾，必致喪師辱國，身亦危矣。</p><p>○　問營商：可斷不斷，因循失時，耗損必大。</p><p>○　問功名：必不能保其終也。</p><p>○　問婚姻：有懼內之象，難期偕老，兇。</p><p>○　問家宅：主有喪，兇。</p><p>○　問六甲：生女。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>明治二十四年，佔國運治亂，筮得《巽》》之《井》。</p><p>斷曰：上九處卦之極，極則思反，正當有為之時，上爻地甚高，事既多，任事愈重，威權在手，正可獨斷獨行。國家當此隆會，得此人材，奮然振作，力求富強，不以巽懦自安，則反弱為強，轉貧為富，不難旦夕期之。所患安於目前，不期上理，委靡不振，甘居人下，一切邦交等事，皆畏葸聽從，不自爭強，商務來往，既喪其財，國事交涉，又喪其威，是所謂“喪其資斧”也。維新以來，政府所急急圖治者，雖以取法歐美為善策，然所取法者，多在皮毛，未得窮其精蘊，故事事出於歐美之下，是即所謂“巽在床下”也。為今之計，當重申命令，相期與天下更新，無因循，無苟且，當奮斧鉞之威，以行其剛巽之志，斯武務修明，即駕於歐美之上不難矣。是治道日隆之休也，所願秉國政者努力圖之！</p>',103)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
